package me.kright.gametools.pga3d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer


/**
 * A rotor: rotation around an axis passing through the origin, applied with rotor.sandwich(obj).
 * A rotor is the exponent of a Pga3dBivectorBulk (bivectorBulk.exp), and rotor.log returns that bivector back.
 *
 * Variable fields: s, xy, xz, yz.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga3d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga3dRotor(s: Double = 0.0,
                            xy: Double = 0.0,
                            xz: Double = 0.0,
                            yz: Double = 0.0) derives CanEqual, FlatDoubleSerializer:

  override def toString: String =
    s"Pga3dRotor(s = $s, xy = $xy, xz = $xz, yz = $yz)"

  def dual: Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = yz,
      wy = -xz,
      wz = xy,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      i = s,
    )

  def bulk: Pga3dRotor =
    this

  @targetName("unaryMinus")
  def unary_- : Pga3dRotor =
    Pga3dRotor(
      s = -s,
      xy = -xy,
      xz = -xz,
      yz = -yz,
    )

  def reverse: Pga3dRotor =
    Pga3dRotor(
      s = s,
      xy = -xy,
      xz = -xz,
      yz = -yz,
    )

  def antiReverse: Pga3dRotor =
    Pga3dRotor(
      s = s,
      xy = -xy,
      xz = -xz,
      yz = -yz,
    )

  def bulkNormSquare: Double =
    (s * s + xy * xy + xz * xz + yz * yz)

  def bulkNorm: Double =
    Math.sqrt(bulkNormSquare)

  def normalizedByBulk =
    this / bulkNorm

  def normSquare: Double =
    (s * s + xy * xy + xz * xz + yz * yz)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga3dRotor =
    Pga3dRotor(
      s = r * s,
      xy = r * xy,
      xz = r * xz,
      yz = r * yz,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga3dRotor =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga3dRotor): Pga3dRotor =
    Pga3dRotor(
      s = (r.s + s),
      xy = (r.xy + xy),
      xz = (r.xz + xz),
      yz = (r.yz + yz),
    )

  @targetName("minus")
  def -(r: Pga3dRotor): Pga3dRotor =
    Pga3dRotor(
      s = (s - r.s),
      xy = (xy - r.xy),
      xz = (xz - r.xz),
      yz = (yz - r.yz),
    )

  def madd(r: Pga3dRotor, mult: Double): Pga3dRotor =
    Pga3dRotor(
      s = (s + mult * r.s),
      xy = (xy + mult * r.xy),
      xz = (xz + mult * r.xz),
      yz = (yz + mult * r.yz),
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga3dRotor): Pga3dRotor =
    Pga3dRotor(
      s = s * r.s,
      xy = xy * r.xy,
      xz = xz * r.xz,
      yz = yz * r.yz,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga3dRotor =
    Pga3dRotor(
      s = 1.0 / s,
      xy = 1.0 / xy,
      xz = 1.0 / xz,
      yz = 1.0 / yz,
    )

  def log: Pga3dBivectorBulk =
    val scalar = s
    if (s < 0.0) {
      return (-this).log
    }

    val lenXYZ = Math.sqrt(xy * xy + xz * xz + yz * yz)
    val angle = Math.atan2(lenXYZ, scalar)

    // for a normalized rotor sin(angle) = lenXYZ, so this is angle / sin(angle); the series branch:
    // x/sin(x) = 1 / (sin(x)/x) = 1 / (1 - x^2/6 + x^4/120 - ...);
    // substitute v = x^2/6 - x^4/120 + ... into 1/(1 - v) = 1 + v + v^2 + ...:
    //   x/sin(x) = 1 + x^2/6 + (1/36 - 1/120)*x^4 + ...
    //            = 1 + x^2/6 + 7*x^4/360 + ...
    // at x <= 1e-5 the dropped 7*x^4/360 <= 2e-22 relative term is far below 1e-17,
    // so the second-order form is exact in double
    val b = if (Math.abs(angle) > 1e-5) {
      angle / lenXYZ
    } else {
      1.0 + angle * angle / 6.0
    }

    Pga3dBivectorBulk(
      xy = b * xy,
      xz = b * xz,
      yz = b * yz,
    )


  /** the fractional power of the motion: pow(0.5) is the half motion, pow(2.0) applies it twice */
  def pow(t: Double): Pga3dRotor =
    log.exp(t)

  def toMultivector: Pga3dMultivector =
    Pga3dMultivector(
      s = s,
      w = 0.0,
      x = 0.0,
      y = 0.0,
      z = 0.0,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = xy,
      xz = xz,
      yz = yz,
      wxy = 0.0,
      wxz = 0.0,
      wyz = 0.0,
      xyz = 0.0,
      i = 0.0,
    )

  def toMotor: Pga3dMotor =
    Pga3dMotor(
      s = s,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = xy,
      xz = xz,
      yz = yz,
      i = 0.0,
    )

  def toBivectorUnsafe: Pga3dBivector =
    Pga3dBivector(
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = xy,
      xz = xz,
      yz = yz,
    )

  def toProjectiveTranslatorUnsafe: Pga3dProjectiveTranslator =
    Pga3dProjectiveTranslator(
      s = s,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
    )

  def toBivectorBulkUnsafe: Pga3dBivectorBulk =
    Pga3dBivectorBulk(
      xy = xy,
      xz = xz,
      yz = yz,
    )

  def axisX: Pga3dVector =
    Pga3dVector(
      x = (s * s + yz * yz - xy * xy - xz * xz),
      y = 2.0 * (-s * xy - xz * yz),
      z = 2.0 * (xy * yz - s * xz),
    )

  def axisY: Pga3dVector =
    Pga3dVector(
      x = 2.0 * (s * xy - xz * yz),
      y = (s * s + xz * xz - xy * xy - yz * yz),
      z = 2.0 * (-s * yz - xy * xz),
    )

  def axisZ: Pga3dVector =
    Pga3dVector(
      x = 2.0 * (s * xz + xy * yz),
      y = 2.0 * (s * yz - xy * xz),
      z = (s * s + xy * xy - xz * xz - yz * yz),
    )

  def projectToRotationInPlane(plane: Pga3dPlaneCentral): Pga3dRotor =
    val q = this.normalizedByNorm
    val qPart = Pga3dRotor.rotation(q.sandwich(plane), plane)
    return qPart.geometric(q)

  def restoreRotationInPlane(plane: Pga3dPlaneCentral): Double =
    val q0 = this.projectToRotationInPlane(plane)
    val logDual = q0.log.dual
    return 2.0 * (logDual.wx * plane.x + logDual.wy * plane.y + logDual.wz * plane.z) / plane.norm

  def restoreRotationInPlaneX: Double =
    restoreRotationInPlane(Pga3dPlaneCentral(1, 0, 0))

  def restoreRotationInPlaneY: Double =
    restoreRotationInPlane(Pga3dPlaneCentral(0, 1, 0))

  def restoreRotationInPlaneZ: Double =
    restoreRotationInPlane(Pga3dPlaneCentral(0, 0, 1))

  /**
   * Spherical linear interpolation along the geodesic from this (t = 0) to b (t = 1),
   * with constant angular velocity. Computes this * (this.reverse.geometric(b))^t via log/exp.
   * Assumes both this and b are normalized; the result is normalized.
   * Near-antipodal inputs (b close to -this) are ill-conditioned: the geodesic is undefined
   * there and the interpolation direction becomes numerically unstable.
   */
  def slerp(b: Pga3dRotor, t: Double): Pga3dRotor =
    this.geometric(this.reverse.geometric(b).log.exp(t))

  /**
   * Normalized linear interpolation: the componentwise lerp this * (1 - t) + b * t, renormalized.
   * A fast APPROXIMATION of slerp: the angular velocity is not constant, so intermediate values
   * deviate from the true geodesic. The error is negligible for small angles between this and b
   * and grows toward the midpoint of large rotations. Assumes both inputs are normalized.
   */
  def nlerp(b: Pga3dRotor, t: Double): Pga3dRotor =
    (this * (1.0 - t) + b * t).normalizedByNorm

  infix def geometric(r: Pga3dMotor): Pga3dMotor =
    Pga3dMotor(
      s = (r.s * s - r.xy * xy - r.xz * xz - r.yz * yz),
      wx = (r.wx * s + r.wy * xy + r.wz * xz - r.i * yz),
      wy = (r.i * xz + r.wy * s + r.wz * yz - r.wx * xy),
      wz = (r.wz * s - r.i * xy - r.wx * xz - r.wy * yz),
      xy = (r.s * xy + r.xy * s + r.xz * yz - r.yz * xz),
      xz = (r.s * xz + r.xz * s + r.yz * xy - r.xy * yz),
      yz = (r.s * yz + r.xy * xz + r.yz * s - r.xz * xy),
      i = (r.i * s + r.wx * yz + r.wz * xy - r.wy * xz),
    )

  infix def geometric(r: Pga3dPlane): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = r.w * s,
      x = (r.x * s + r.y * xy + r.z * xz),
      y = (r.y * s + r.z * yz - r.x * xy),
      z = (r.z * s - r.x * xz - r.y * yz),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = r.w * xy,
      wxz = r.w * xz,
      wyz = r.w * yz,
      xyz = (r.x * yz + r.z * xy - r.y * xz),
      i = 0.0,
    )

  infix def geometric(r: Pga3dBivector): Pga3dMotor =
    Pga3dMotor(
      s = (-r.xy * xy - r.xz * xz - r.yz * yz),
      wx = (r.wx * s + r.wy * xy + r.wz * xz),
      wy = (r.wy * s + r.wz * yz - r.wx * xy),
      wz = (r.wz * s - r.wx * xz - r.wy * yz),
      xy = (r.xy * s + r.xz * yz - r.yz * xz),
      xz = (r.xz * s + r.yz * xy - r.xy * yz),
      yz = (r.xy * xz + r.yz * s - r.xz * xy),
      i = (r.wx * yz + r.wz * xy - r.wy * xz),
    )

  infix def geometric(r: Pga3dProjectivePoint): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * yz + r.z * xy - r.y * xz),
      x = -r.w * yz,
      y = r.w * xz,
      z = -r.w * xy,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.x * xz + r.y * yz - r.z * s),
      wxz = (r.y * s + r.z * yz - r.x * xy),
      wyz = (-r.x * s - r.y * xy - r.z * xz),
      xyz = r.w * s,
      i = 0.0,
    )

  infix def geometric(r: Pga3dRotor): Pga3dRotor =
    Pga3dRotor(
      s = (r.s * s - r.xy * xy - r.xz * xz - r.yz * yz),
      xy = (r.s * xy + r.xy * s + r.xz * yz - r.yz * xz),
      xz = (r.s * xz + r.xz * s + r.yz * xy - r.xy * yz),
      yz = (r.s * yz + r.xy * xz + r.yz * s - r.xz * xy),
    )

  infix def geometric(r: Pga3dProjectiveTranslator): Pga3dMotor =
    Pga3dMotor(
      s = r.s * s,
      wx = (r.wx * s + r.wy * xy + r.wz * xz),
      wy = (r.wy * s + r.wz * yz - r.wx * xy),
      wz = (r.wz * s - r.wx * xz - r.wy * yz),
      xy = r.s * xy,
      xz = r.s * xz,
      yz = r.s * yz,
      i = (r.wx * yz + r.wz * xy - r.wy * xz),
    )

  infix def geometric(r: Pga3dTranslator): Pga3dMotor =
    Pga3dMotor(
      s = s,
      wx = (r.wx * s + r.wy * xy + r.wz * xz),
      wy = (r.wy * s + r.wz * yz - r.wx * xy),
      wz = (r.wz * s - r.wx * xz - r.wy * yz),
      xy = xy,
      xz = xz,
      yz = yz,
      i = (r.wx * yz + r.wz * xy - r.wy * xz),
    )

  infix def geometric(r: Pga3dVector): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * yz + r.z * xy - r.y * xz),
      x = 0.0,
      y = 0.0,
      z = 0.0,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.x * xz + r.y * yz - r.z * s),
      wxz = (r.y * s + r.z * yz - r.x * xy),
      wyz = (-r.x * s - r.y * xy - r.z * xz),
      xyz = 0.0,
      i = 0.0,
    )

  infix def geometric(r: Pga3dPoint): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * yz + r.z * xy - r.y * xz),
      x = -yz,
      y = xz,
      z = -xy,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.x * xz + r.y * yz - r.z * s),
      wxz = (r.y * s + r.z * yz - r.x * xy),
      wyz = (-r.x * s - r.y * xy - r.z * xz),
      xyz = s,
      i = 0.0,
    )

  infix def geometric(r: Pga3dPlaneCentral): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = 0.0,
      x = (r.x * s + r.y * xy + r.z * xz),
      y = (r.y * s + r.z * yz - r.x * xy),
      z = (r.z * s - r.x * xz - r.y * yz),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = 0.0,
      wxz = 0.0,
      wyz = 0.0,
      xyz = (r.x * yz + r.z * xy - r.y * xz),
