  infix def geometric(r: Pga3dPseudoScalar): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = -r.i * yz,
      wy = r.i * xz,
      wz = -r.i * xy,
      xy = 0.0,
