      y = (2.0 * (r.x * (sMxy - xzMyz) + r.z * (-sMyz - xyMxz)) + r.y * (sMs + xzMxz - xyMxy - yzMyz)),
      z = (2.0 * (r.x * (sMxz + xyMyz) + r.y * (sMyz - xyMxz)) + r.z * (sMs + xyMxy - xzMxz - yzMyz)),
    )

  infix def reverseSandwich(r: Pga3dBivectorBulk): Pga3dBivectorBulk =
    val sMs = s * s
    val sMxy = s * xy
    val sMxz = s * xz
    val sMyz = s * yz
    val xyMxy = xy * xy
    val xyMxz = xy * xz
    val xyMyz = xy * yz
    val xzMxz = xz * xz
    val xzMyz = xz * yz
    val yzMyz = yz * yz
    Pga3dBivectorBulk(
      xy = (2.0 * (r.xz * (xyMxz - sMyz) + r.yz * (sMxz + xyMyz)) + r.xy * (sMs + xyMxy - xzMxz - yzMyz)),
      xz = (2.0 * (r.xy * (sMyz + xyMxz) + r.yz * (xzMyz - sMxy)) + r.xz * (sMs + xzMxz - xyMxy - yzMyz)),
      yz = (2.0 * (r.xy * (xyMyz - sMxz) + r.xz * (sMxy + xzMyz)) + r.yz * (sMs + yzMyz - xyMxy - xzMxz)),
    )

  infix def reverseSandwich(r: Pga3dBivectorWeight): Pga3dBivectorWeight =
    val sMs = s * s
    val sMxy = s * xy
    val sMxz = s * xz
    val sMyz = s * yz
    val xyMxy = xy * xy
    val xyMxz = xy * xz
    val xyMyz = xy * yz
    val xzMxz = xz * xz
    val xzMyz = xz * yz
    val yzMyz = yz * yz
    Pga3dBivectorWeight(
      wx = (2.0 * (r.wy * (-sMxy - xzMyz) + r.wz * (xyMyz - sMxz)) + r.wx * (sMs + yzMyz - xyMxy - xzMxz)),
      wy = (2.0 * (r.wx * (sMxy - xzMyz) + r.wz * (-sMyz - xyMxz)) + r.wy * (sMs + xzMxz - xyMxy - yzMyz)),
      wz = (2.0 * (r.wx * (sMxz + xyMyz) + r.wy * (sMyz - xyMxz)) + r.wz * (sMs + xyMxy - xzMxz - yzMyz)),
    )

  infix def reverseSandwich(r: Pga3dPseudoScalar): Pga3dPseudoScalar =
    Pga3dPseudoScalar(
      i = r.i * (s * s + xy * xy + xz * xz + yz * yz),
    )

  infix def reverseSandwich(r: Pga3dPointCenter.type): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = 0.0,
      y = 0.0,
      z = 0.0,
      w = (s * s + xy * xy + xz * xz + yz * yz),
    )

  infix def cross(r: Pga3dMotor): Pga3dBivector =
    Pga3dBivector(
      wx = (r.wy * xy + r.wz * xz),
      wy = (r.wz * yz - r.wx * xy),
      wz = (-r.wx * xz - r.wy * yz),
      xy = (r.xz * yz - r.yz * xz),
      xz = (r.yz * xy - r.xy * yz),
      yz = (r.xy * xz - r.xz * xy),
    )

  infix def cross(r: Pga3dPlane): Pga3dPlaneCentral =
    Pga3dPlaneCentral(
      x = (r.y * xy + r.z * xz),
      y = (r.z * yz - r.x * xy),
      z = (-r.x * xz - r.y * yz),
    )

  infix def cross(r: Pga3dBivector): Pga3dBivector =
    Pga3dBivector(
      wx = (r.wy * xy + r.wz * xz),
      wy = (r.wz * yz - r.wx * xy),
      wz = (-r.wx * xz - r.wy * yz),
      xy = (r.xz * yz - r.yz * xz),
      xz = (r.yz * xy - r.xy * yz),
      yz = (r.xy * xz - r.xz * xy),
    )

  infix def cross(r: Pga3dProjectivePoint): Pga3dVector =
    Pga3dVector(
      x = (r.y * xy + r.z * xz),
      y = (r.z * yz - r.x * xy),
      z = (-r.x * xz - r.y * yz),
    )

  infix def cross(r: Pga3dRotor): Pga3dBivectorBulk =
    Pga3dBivectorBulk(
      xy = (r.xz * yz - r.yz * xz),
      xz = (r.yz * xy - r.xy * yz),
      yz = (r.xy * xz - r.xz * xy),
    )

  infix def cross(r: Pga3dProjectiveTranslator): Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = (r.wy * xy + r.wz * xz),
      wy = (r.wz * yz - r.wx * xy),
      wz = (-r.wx * xz - r.wy * yz),
    )

  infix def cross(r: Pga3dTranslator): Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = (r.wy * xy + r.wz * xz),
      wy = (r.wz * yz - r.wx * xy),
      wz = (-r.wx * xz - r.wy * yz),
    )

  infix def cross(r: Pga3dVector): Pga3dVector =
    Pga3dVector(
      x = (r.y * xy + r.z * xz),
      y = (r.z * yz - r.x * xy),
      z = (-r.x * xz - r.y * yz),
    )

  infix def cross(r: Pga3dPoint): Pga3dVector =
    Pga3dVector(
      x = (r.y * xy + r.z * xz),
      y = (r.z * yz - r.x * xy),
      z = (-r.x * xz - r.y * yz),
    )

  infix def cross(r: Pga3dPlaneCentral): Pga3dPlaneCentral =
    Pga3dPlaneCentral(
      x = (r.y * xy + r.z * xz),
      y = (r.z * yz - r.x * xy),
      z = (-r.x * xz - r.y * yz),
    )

  infix def cross(r: Pga3dBivectorBulk): Pga3dBivectorBulk =
    Pga3dBivectorBulk(
      xy = (r.xz * yz - r.yz * xz),
      xz = (r.yz * xy - r.xy * yz),
      yz = (r.xy * xz - r.xz * xy),
    )

  infix def cross(r: Pga3dBivectorWeight): Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = (r.wy * xy + r.wz * xz),
      wy = (r.wz * yz - r.wx * xy),
      wz = (-r.wx * xz - r.wy * yz),
    )


object Pga3dRotor:

  inline val componentsCount = 4

  val zero: Pga3dRotor = Pga3dRotor(0.0, 0.0, 0.0, 0.0)

  val id: Pga3dRotor = Pga3dRotor(1.0, 0.0, 0.0, 0.0)

  def rotation(from: Pga3dPlaneCentral, to: Pga3dPlaneCentral): Pga3dRotor = {
    import me.kright.gametools.mathutil.ExactArith.diffOfProducts

    // not sqrt(from.normSquare * to.normSquare): the product overflows/underflows
    // for extreme magnitudes (~1e100 or ~1e-100) where each norm alone is still fine
    val norm = from.norm * to.norm
    val q2a = to.geometric(from) / norm
    val dot = q2a.s

    // the -0.9 threshold keeps (1.0 + dot) >= 0.1, so the half-angle branch loses
    // at most ~2e-15 relative to the dot rounding; angles closer to pi take the
    // exact-wedge branch below, which stays ~1e-15 all the way to pi
    if (dot > -0.9) {
      val newCos = Math.sqrt((1.0 + dot) / 2)
      val newSinDivSin2 = 0.5 / newCos
      return Pga3dRotor(newCos, q2a.xy * newSinDivSin2, q2a.xz * newSinDivSin2, q2a.yz * newSinDivSin2)
    }

    // near pi the wedge components of q2a cancel catastrophically (~1e-17 absolute
    // noise, which would tilt the axis by ~1e-17/sin2a), so the axis is recomputed
    // with error-free products
    val invNorm = 1.0 / norm
    val bxy = diffOfProducts(from.y, to.x, from.x, to.y) * invNorm
    val bxz = diffOfProducts(from.z, to.x, from.x, to.z) * invNorm
    val byz = diffOfProducts(from.z, to.y, from.y, to.z) * invNorm
    val sin2a = Math.sqrt(bxy * bxy + bxz * bxz + byz * byz)

    if (sin2a > 0.0) {
      // rotation by (pi - eps): the dot guard bounds sin2a <= sin(acos(0.9)) ~ 0.44,
      // where asin is well-conditioned - unlike atan2 near pi, whose ~ulp(pi)
      // absolute error would be ~1e-16/eps relative in s
      val eps = Math.asin(sin2a)
      val axisMult = Math.cos(eps * 0.5) / sin2a
      return Pga3dRotor(Math.sin(eps * 0.5), bxy * axisMult, bxz * axisMult, byz * axisMult)
    }

    // exactly antipodal inputs: the axis is any direction orthogonal to from
    if (Math.abs(from.x) > Math.abs(from.z)) {
      return Pga3dRotor(0.0, 0.0, -from.x, -from.y).normalizedByNorm
    }
    return Pga3dRotor(0.0, from.y, from.z, 0.0).normalizedByNorm
  }

  def rotation(from: Pga3dVector, to: Pga3dVector): Pga3dRotor =
    rotation(from.dual, to.dual)

  def fromAxes(axisX: Pga3dVector, axisY: Pga3dVector, axisZ: Pga3dVector): Pga3dRotor = {
    val m00 = axisX.x
    val m10 = axisX.y
    val m20 = axisX.z
    val m01 = axisY.x
    val m11 = axisY.y
    val m21 = axisY.z
    val m02 = axisZ.x
    val m12 = axisZ.y
    val m22 = axisZ.z

    val tr = m00 + m11 + m22
    val max = Math.max(tr, Math.max(m00, Math.max(m11, m22)))

    if (tr == max) {
      val s = Math.sqrt(1.0 + tr)
      val invS = 0.5 / s
      Pga3dRotor(
        s = 0.5 * s,
        xy = (m01 - m10) * invS,
        xz = (m02 - m20) * invS,
        yz = (m12 - m21) * invS
      )
    } else if (m00 == max) {
      val yz = Math.sqrt(1.0 + m00 - m11 - m22)
      val invYZ = 0.5 / yz
      Pga3dRotor(
        s = (m12 - m21) * invYZ,
        xy = (m20 + m02) * invYZ,
        xz = -(m10 + m01) * invYZ,
        yz = 0.5 * yz
      )
    } else if (m11 == max) {
      val xz = Math.sqrt(1.0 - m00 + m11 - m22)
      val invXZ = 0.5 / xz
      Pga3dRotor(
        s = (m02 - m20) * invXZ,
        xy = -(m12 + m21) * invXZ,
        xz = 0.5 * xz,
        yz = -(m10 + m01) * invXZ
      )
    } else {
      val xy = Math.sqrt(1.0 - m00 - m11 + m22)
      val invXY = 0.5 / xy
      Pga3dRotor(
        s = (m01 - m10) * invXY,
        xy = 0.5 * xy,
        xz = -(m12 + m21) * invXY,
        yz = (m20 + m02) * invXY
      )
    }
  }